const RECOMMENDER="/* Small deterministic online models. Runs exclusively in a dedicated worker. */\nlet profile={votes:{}},items=[],vectors=new Map(),dimensions=0;\nconst sigmoid=x=>1/(1+Math.exp(-Math.max(-20,Math.min(20,x))));\nfunction dot(w,x){let v=0;for(const [i,a] of x)v+=w[i]*a;return v}\nfunction learn(w,x,y,weight=1){const error=y-sigmoid(dot(w,x));for(const [i,a] of x)w[i]+=.12*weight*(error*a-.015*w[i])}\nfunction initialize(catalog){const names=new Map([['bias',0]]);items=catalog;vectors.clear();for(const p of items){const fs=p.traits||[];const values=['bias',...fs];const types=fs.filter(f=>f.startsWith('type:'));const color=fs.find(f=>f.startsWith('color_id:'));for(const t of types)if(color)values.push(t+'|'+color);vectors.set(p.id,values.map(f=>{if(!names.has(f))names.set(f,names.size);return[names.get(f),f==='bias'?1:1/Math.sqrt(Math.max(1,values.length-1))]}))}dimensions=names.size}\nfunction recommend(state){const started=performance.now(),yes=new Float32Array(dimensions),rank=new Float32Array(dimensions),counts=new Float32Array(dimensions);const observations=Object.entries(state.votes||{}).sort((a,b)=>(a[1].time||0)-(b[1].time||0));for(let epoch=0;epoch<3;epoch++)for(const [id,v] of observations){const x=vectors.get(+id);if(x)learn(yes,x,v.value==='yes'?1:0)}for(const [id] of observations)for(const [i,a] of vectors.get(+id)||[])counts[i]+=a*a;\nconst repeats={};for(const e of Object.values(state.encounters||{})){const x=vectors.get(e.id);if(x)learn(yes,x,e.value==='yes'?1:0,.35);const r=repeats[e.id]||(repeats[e.id]=[1,1]);r[e.value==='yes'?0:1]++}\nfor(let epoch=0;epoch<3;epoch++)for(const e of state.comparisons||[]){const a=vectors.get(e.ids?.[0]),b=vectors.get(e.ids?.[1]);if(!a||!b)continue;const diff=new Map(a);for(const [i,v] of b)diff.set(i,(diff.get(i)||0)-v);learn(rank,[...diff],e.winner===2?.5:e.winner===0?1:0)}\nconst scores=items.map(p=>{const x=vectors.get(p.id),personal=sigmoid(dot(yes,x)),utility=dot(rank,x);const uncertainty=Math.sqrt(x.reduce((n,[i,a])=>n+a*a/(1+counts[i]),0));const prior=p.communityVotes2020?Math.log1p(p.communityVotes2020)/Math.log1p(140559):.45;const familiarity=1/(1+uncertainty*3);const strength=Math.min(.85,observations.length/100)*familiarity;return {id:p.id,p:personal,u:uncertainty,score:strength*personal+(1-strength)*prior+.04*Math.tanh(utility),consistency:repeats[p.id]||null}});\nconst unseen=scores.filter(p=>!state.votes?.[p.id]),selected=[],used=new Set(),ranked=[...unseen].sort((a,b)=>b.score-a.score||a.id-b.id),exploration=[...unseen].sort((a,b)=>(b.score*.4+b.u*.6)-(a.score*.4+a.u*.6)||a.id-b.id);let slot=0;for(let r=0,e=0;selected.length<unseen.length;slot++){const list=slot%5===3?exploration:ranked;let index=slot%5===3?e:r;while(index<list.length&&used.has(list[index].id))index++;if(index>=list.length)break;used.add(list[index].id);selected.push(list[index].id);if(slot%5===3)e=index+1;else r=index+1}return {ids:selected,scores,ms:performance.now()-started,observations:observations.length}}\nself.onmessage=({data})=>{try{if(data.type==='init')initialize(data.catalog);if(data.state)profile=data.state;if(data.type==='delta'){for(const [id,v] of Object.entries(data.votes||{})){if(v)profile.votes[id]=v;else delete profile.votes[id]}profile.encounters=data.encounters;profile.comparisons=data.comparisons}if(data.state||data.type==='delta')self.postMessage({revision:data.revision,...recommend(profile)})}catch(e){self.postMessage({error:String(e)})}};\n";
const CARD_RESOURCE_JS="/* Optional, immutable resources. No request occurs until a loader is called. */\n(()=>{\n'use strict';\nconst manifest=window.POKE_CARD_RESOURCES,slots={alternatives:{status:'idle'},proxies:{status:'idle'}};\nfunction validate(kind,d){\n if(d?.schema!==1||d.dataVersion!==manifest.dataVersion)throw Error('Versi\u00f3n de recursos incompatible');\n if(kind==='alternatives'){\n  if(!d.pokemon||typeof d.pokemon!=='object')throw Error('Alternativas inv\u00e1lidas');\n  for(const [id,rows] of Object.entries(d.pokemon))if(!/^\\d+$/.test(id)||!Array.isArray(rows)||rows.length>2||rows.some(r=>!Array.isArray(r)||r.length!==4||r.some(x=>typeof x!=='string')||!r[1].startsWith('https://')))throw Error('Alternativa inv\u00e1lida');\n }else{\n  if(!Array.isArray(d.sets)||d.sets.some(s=>typeof s!=='string')||!d.prints)throw Error('Proxies inv\u00e1lidos');\n  for(const r of Object.values(d.prints))if(!Array.isArray(r)||r.length!==3||!Number.isInteger(r[0])||!d.sets[r[0]]||typeof r[1]!=='string'||typeof r[2]!=='string')throw Error('Proxy inv\u00e1lido');\n }\n return d;\n}\nfunction load(kind){const s=slots[kind];if(s.data)return Promise.resolve(s.data);if(s.promise)return s.promise;s.status='loading';\n const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);\n s.promise=fetch(manifest[kind],{signal:controller.signal}).then(r=>{if(!r.ok)throw Error('No se pudo cargar el recurso');return r.json()}).then(d=>{s.data=validate(kind,d);s.status='ready';return s.data}).catch(e=>{s.status='error';throw e}).finally(()=>{clearTimeout(timer);s.promise=null});return s.promise;\n}\nwindow.PokeCardResources={loadAlternatives:()=>load('alternatives'),loadProxies:()=>load('proxies'),getAlternatives:id=>slots.alternatives.data?.pokemon[id]||[],getProxy:id=>{const d=slots.proxies.data,r=d?.prints[id];return r?{set:d.sets[r[0]],number:r[1],name:r[2]}:null},getStatus:()=>({alternatives:slots.alternatives.status,proxies:slots.proxies.status})};\n})();\n";
